// Last 24 hours of CallTurns rows -> one record per call -> metrics + a transcript digest for Claude.
const tz = $env.BUSINESS_TIMEZONE || 'Asia/Kolkata';
const since = Date.now() - 24 * 3600 * 1000;
const rows = $input.all().map(i => i.json)
  .filter(r => r.session_id && Date.parse(r.timestamp) >= since)
  .sort((a, b) => Date.parse(a.timestamp) - Date.parse(b.timestamp));

const INTENT_RANK = ['unknown', 'general', 'enquiry', 'booking', 'complaint'];
const EMOTION_RANK = ['neutral', 'happy', 'confused', 'urgent', 'angry', 'wants_escalation'];
const higher = (rank, a, b) => (rank.indexOf(b) > rank.indexOf(a) ? b : a);
const yes = v => String(v).trim().toLowerCase() === 'yes';

const calls = new Map();
for (const r of rows) {
  if (!calls.has(r.session_id)) {
    calls.set(r.session_id, { session_id: r.session_id, phone: r.phone, started: r.timestamp, turns: [],
      intent: 'unknown', emotion: 'neutral', languages: {}, booked: false, escalated: false });
  }
  const c = calls.get(r.session_id);
  c.turns.push(r);
  c.intent = higher(INTENT_RANK, c.intent, String(r.intent || 'unknown'));
  c.emotion = higher(EMOTION_RANK, c.emotion, String(r.emotion || 'neutral'));
  if (r.language) c.languages[r.language] = (c.languages[r.language] || 0) + 1;
  c.booked = c.booked || yes(r.booking_complete);
  c.escalated = c.escalated || yes(r.escalated);
}

const list = [...calls.values()];
const count = (key) => list.reduce((acc, c) => { acc[key(c)] = (acc[key(c)] || 0) + 1; return acc; }, {});
const pct = (n, d) => (d > 0 ? ((n / d) * 100).toFixed(1) + '%' : 'N/A');
const mainLang = c => Object.entries(c.languages).sort((a, b) => b[1] - a[1])[0]?.[0] || 'unknown';
const totalTurns = list.reduce((n, c) => n + c.turns.length, 0);
const bookingCalls = list.filter(c => c.intent === 'booking' || c.booked).length;
const booked = list.filter(c => c.booked).length;
const escalated = list.filter(c => c.escalated).length;

const metrics = {
  total_calls: list.length,
  total_turns: totalTurns,
  avg_turns: list.length ? Math.round((totalTurns / list.length) * 10) / 10 : 0,
  intent_breakdown: count(c => c.intent),
  language_breakdown: count(mainLang),
  emotion_breakdown: count(c => c.emotion),
  bookings_completed: booked,
  booking_conversion_rate: pct(booked, bookingCalls),
  escalation_rate: pct(escalated, list.length)
};

// Transcript digest for the AI review, capped well under Claude's input and a Sheets cell
const MAX = 60000;
let digest = '';
for (const [i, c] of list.entries()) {
  const head = `Call ${i + 1} (${mainLang(c)}, ${c.intent}${c.booked ? ', booked' : ''}${c.escalated ? ', escalated' : ''}):\n`;
  const body = c.turns.map(t => `Guest: ${t.caller_text || ''}\nPriya: ${t.reply_text || ''}`).join('\n');
  const block = head + body + '\n\n';
  if (digest.length + block.length > MAX) { digest += `[${list.length - i} more calls not included]`; break; }
  digest += block;
}

// The report covers the previous day in the venue's timezone (it runs just after midnight)
const reportDate = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(new Date(Date.now() - 24 * 3600 * 1000));

return [{ json: { report_date: reportDate, has_calls: list.length > 0, metrics, digest } }];

