// One DailyReports row. Works with or without the AI review (no calls, or Claude unavailable).
const s = $('Build Daily Summary').first().json;
const ai = $input.first().json;
let analysis;
if (!s.has_calls) analysis = 'No calls in the last 24 hours.';
else {
  try { analysis = ai.content[0].text; }
  catch (e) { analysis = `AI analysis unavailable: ${ai.error ? JSON.stringify(ai.error).slice(0, 300) : 'no response'}`; }
}

return [{ json: {
  date: s.report_date,
  total_calls: s.metrics.total_calls,
  bookings_completed: s.metrics.bookings_completed,
  booking_rate: s.metrics.booking_conversion_rate,
  escalation_rate: s.metrics.escalation_rate,
  metrics_json: JSON.stringify(s.metrics),
  ai_analysis: String(analysis).slice(0, 45000),
  status: 'pending_review'
} }];

